REFERENCES = json.loads((ROOT / 'references.json').read_text())
PUBLIC_REFERENCES = [{k:v for k,v in r.items() if k in ('id','name','date','summary','scope','public','images','imageDimensions','program','coverPosition')} for r in REFERENCES]
JS = (ROOT / 'references.js').read_text().replace('__REFERENCES__', json.dumps(PUBLIC_REFERENCES,ensure_ascii=False)) + '\n' + (ROOT / 'timeline-icons.js').read_text() + '\n' + (ROOT / 'visitor.js').read_text() + '\n' + (ROOT / 'scroll-guide.js').read_text()
CSS += (ROOT / 'visitor.css').read_text()
CSS += (ROOT / 'program-design.css').read_text()
