FILES = [('compare.html','三版比較'),('a-program-catalog.html','A 活動方案'),('b-event-journey.html','B 活動旅程'),('c-needs-planner.html','C 需求配對')]

def shell(title, mode, body, filename):
    guide = ('''<nav class="activity-scroll-guide" id="activity-scroll-guide" aria-label="三款活動閱讀位置" hidden><div class="guide-segments">''' + ''.join(f'<button type="button" class="guide-stop {p["id"]}" id="guide-{p["id"]}" aria-label="前往：{p["name"]}"><span class="guide-track" aria-hidden="true"><span class="guide-fill"></span></span><span class="guide-name">{p["name"]}</span></button>' for p in PROGRAMS) + '''</div><span class="sr-only" id="guide-status" role="status" aria-live="polite"></span></nav>''') if mode == 'catalog' else '' 
    nav=''.join(f'<a href="{f}" class="{"active" if f==filename or (filename=='index.html' and f=='b-event-journey.html') else ""}"'+(' aria-current="page"' if f==filename or (filename=='index.html' and f=='b-event-journey.html') else '')+f'>{t}</a>' for f,t in FILES)
    return f'''<!doctype html>
<html lang="zh-Hant-HK"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="VTM XR 活動服務：探索工作坊、團隊協作挑戰與行業情境體驗，查看活動流程及過往活動相片。"><title>{title}｜VTM 活動服務</title><style>{CSS}</style></head>
<body data-mode="{mode}"><a href="#main" class="skip-link">跳到主要內容</a><header class="topbar"><div class="wrap brandrow"><a class="brand" href="index.html"><img src="assets/vtm-logo.svg" alt="VTM Digital" width="70" height="58"><span>XR 活動服務</span></a><nav class="variantnav" aria-label="切換概念版本">{nav}</nav></div></header><div class="reviewbar"><div class="wrap">人數、活動時間及場地可按需要安排。</div></div>{body}{guide}<footer class="wrap footer"><p>VTM Digital · XR 活動服務</p><p>過往活動相片供參考。活動內容及安排可按需要調整。</p><a href="compare.html">查看三版比較</a>　<a href="https://vtmdigital.com/en/contact-us/" target="_blank" rel="noopener noreferrer">VTM 聯絡資料</a></footer><script>{JS.replace('__PROGRAMS__',json.dumps(PROGRAMS,ensure_ascii=False))}</script></body></html>'''

from visitor_layouts import CATALOG, STORY, PLANNER, COMPARE

for filename,title,mode,body in [
    ('index.html','B｜參加者活動旅程','story',STORY),
    ('compare.html','三版比較','home',COMPARE),
    ('a-program-catalog.html','A｜活動方案目錄','catalog',CATALOG),
    ('b-event-journey.html','B｜參加者活動旅程','story',STORY),
    ('c-needs-planner.html','C｜客戶需求配對','planner',PLANNER),
]:
    (DIST/filename).write_text(shell(title,mode,body,filename),encoding='utf-8')

print('Generated 5 HTML pages with local photo assets in', DIST)

